#pragma once
/*
 * The Bergamota identity on the framebuffer (tools/identity/IDENTITY.md): lime halftone ground, the Newton halftone
 * portrait, Archivo pieces as alpha images and JetBrains Mono text. Integer only (Enxerto builds -mgeneral-regs-only).
 * Artwork: art.h, generated by tools/identity/mkidentity.py.
 */
#include <stdint.h>

#define ID_LIME		0xffd7e98aU	/* ground */
#define ID_DOT		0xffc6dc72U	/* the ground's halftone dots */
#define ID_INK		0xff161616U
#define ID_PAPER	0xfff4f3ecU
#define ID_LEAF		0xff1a5933U	/* actions, progress */
#define ID_WHITE	0xffffffffU	/* the giant numerals */
#define ID_ALERT	0xffb3261eU	/* failures */

enum art_font { ART_MONO30, ART_MONO22 };
enum art_image { ART_WORDMARK, ART_NUM_26, ART_NUM_18, ART_PCT };

void art_ground(int x, int y, int w, int h);		/* lime + dots, aligned to the screen so any patch matches */
void art_image(enum art_image im, int x, int y, uint32_t color);
/* The same, touching only screen rows [row0, row1): to restore it under a band that was repainted with art_ground. */
void art_image_rows(enum art_image im, int x, int y, uint32_t color, int row0, int row1);
int art_image_w(enum art_image im);
int art_image_h(enum art_image im);
void art_portrait(int x, int y, int w);			/* height follows the master's aspect; clipped to the screen */
/* The same, touching only screen rows [row0, row1): to restore it under a band that was repainted. */
void art_portrait_rows(int x, int y, int w, int row0, int row1);
int art_portrait_h(int w);
/* Giant Archivo digits ("0123456789-", art.h "big"), set with `gap` px between them; rows [row0, row1) only. */
void art_big(int x, int y, int gap, uint32_t color, const char *s, int row0, int row1);
int art_big_w(const char *s, int gap);
int art_big_h(void);
/* Ink dots growing from nothing at y to solid at y + h, across the screen, over whatever is there: the portrait's
 * coat dissolving into the console below it. Rows [row0, row1) only. */
void art_dissolve(int y, int h, uint32_t color, int row0, int row1);
/* A pill of mono30 text centred on cx; returns its width. art_pill_h: its height. */
int art_pill(int cx, int y, uint32_t bg, uint32_t fg, const char *s);
int art_pill_h(void);
void art_text(enum art_font f, int x, int y, uint32_t color, const char *s);
int art_text_w(enum art_font f, const char *s);
int art_text_h(enum art_font f);
void art_text_centered(enum art_font f, int y, uint32_t color, const char *s);
void art_rrect(int x, int y, int w, int h, int r, uint32_t color);	/* rounded rectangle, anti-aliased corners */
/*
 * The fastboot and charging screens' stage (tools/identity/IDENTITY.md): the wordmark and a state pill at the top,
 * giant white numerals (the caller's, drawn on the ground before art_stage_front), Newton standing on the bottom
 * edge, and his coat dissolving in halftone into the ink console panel that holds the screen's text. Positions of
 * the lower half count from the bottom edge, so sweet's 2400 rows work as well as beryllium's 2246.
 */
#define STAGE_WORD_Y		176
#define STAGE_PILL_Y		290
#define STAGE_PORTRAIT_W	1180		/* fastboot: the hair runs off both edges */
#define STAGE_PANEL_Y		(FB_H - 440)	/* the console panel, ink to the bottom edge */
#define STAGE_DISSOLVE_H	120		/* halftone ramp above the panel */
#define STAGE_NUM_Y		(FB_H - 1866)	/* top of the giant numerals: their foot behind the hair */
#define STAGE_MUTED		0xff858481U	/* paper at 50 % over the ink */
#define STAGE_TRACK		0xff353533U	/* paper at 14 % over the ink: empty bar */
#define STAGE_ALERT		0xffff6a5aU	/* ID_ALERT lightened to read on the ink */
/* Portrait (portrait_w wide, centred), dissolve, panel and wordmark over what is drawn (ground, numerals); rows
 * [row0, row1) only. */
void art_stage_front(int portrait_w, int row0, int row1);

/* The iOS generation the image boots (the giant numerals): ART_NUM_26 unless built with -DENXERTO_IOS=18. */
enum art_image art_ios_numerals(void);
